#define SMOOVstep(v,p) smoothstep((v)-blur, (v)+blur, p)
#define PI 3.141592653589

float avg(vec3 v) { 
    return (v.x + v.y + v.z) / 3.0; 
}
float avg(vec2 v) { 
    return (v.x + v.y) / 2.0; 
}

// (Optional) Return the channel that is greatest
vec3 biggestColor(vec3 c) {
    float m = max(max(c.x, c.y), c.z);
    if(c.x == m) return vec3(1.0, 0.0, 0.0);
    if(c.y == m) return vec3(0.0, 1.0, 0.0);
    if(c.z == m) return vec3(0.0, 0.0, 1.0);
    return vec3(1.0); // fallback, should not happen
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize pixel coordinates [0,1]
    vec2 uv = fragCoord / iResolution.xy;
    float blur = 1.0 / iResolution.y;

    // Set up a stripe grid (nLines stripes across the width)
    float nLines = 15.0;
    float scale = nLines;

    vec4 tex = texture(iChannel0, uv);
    float vscale = 0.5; // adjust this to taste
    float variance = avg(tex.xyz) * vscale;

    float linePattern = SMOOVstep(1.0, 1.0 - fract(uv.x * scale) + variance);

    // The stripe coordinate in [0,1]
    float pos = fract(uv.x * scale);
    vec3 gradColor = vec3(0.0);

    if(pos < variance){
        // Remap pos to [0,1] within the colored region.
        float t = pos / variance;

        float whiteComp = min(tex.r, min(tex.g, tex.b));
        float rComp = tex.r - whiteComp;
        float gComp = tex.g - whiteComp;
        float bComp = tex.b - whiteComp;

        float totalWeight = whiteComp + rComp + gComp + bComp;
        totalWeight = totalWeight > 0.0 ? totalWeight : 1.0;

        // Compute cumulative boundaries (normalized to [0,1]).
        float whiteBound = whiteComp / totalWeight;
        float redBound   = whiteBound + (rComp / totalWeight);
        float greenBound = redBound   + (gComp / totalWeight);
        // Blue occupies the remainder.

        // Choose the band based on t.
        if(t < whiteBound){
            gradColor = vec3(1.0);               // white
        } else if(t < redBound){
            gradColor = vec3(1.0, 0.0, 0.0);      // red
        } else if(t < greenBound){
            gradColor = vec3(0.0, 1.0, 0.0);      // green
        } else {
            gradColor = vec3(0.0, 0.0, 1.0);      // blue
        }
    }

    // Multiply the discrete color with the smooth stripe mask.
    vec3 col = gradColor * linePattern;

    fragColor = vec4(col, 1.0);
}
